			candidate.result.EndLine-candidate.result.StartLine <= 3 &&
			!searchResultHasSignal(candidate.result, "exact-symbol") &&
			!searchNameCoversQuery(candidate.result, q) {
			bm25 *= 0.4
			codeTokenBonus *= 0.5
